const j = $input.first().json;
const topic = String(j.topic || j.mqttTopic || '');
const topicParts = topic.split('/');
const sensorType = (topicParts[topicParts.length - 1] || '').toLowerCase();
const raw = j.message !== undefined ? j.message : j.payload;
const sensorValue = parseFloat(String(raw).trim());
if (Number.isNaN(sensorValue)) {
  throw new Error('Payload no es un número válido');
}
if (!['orp', 'tds', 'ph'].includes(sensorType)) {
  return [];
}
return [
  {
    json: {
      sensor_type: sensorType,
      sensor_value: sensorValue,
      timestamp: new Date().toISOString(),
      raw_topic: topic,
      raw_payload: String(raw),
    },
  },
];

const prep = $('Prepare_Analysis_Data').first().json;
const api = $input.first().json;
const critical = Boolean(api && api.analysis && api.analysis.status === 'critical');
const rec = Array.isArray(api.recommendations) ? api.recommendations : [];
const oa = api.ollama_analysis || {};
const iaOk = oa.model_used && oa.model_used !== 'disabled' && oa.model_used !== 'fallback';
return [
  {
    json: {
      status: 'processed',
      alert: critical,
      sensor_type: prep.sensor_type,
      sensor_value: prep.sensor_value,
      timestamp: prep.timestamp,
      alert_message: critical ? `Alerta ${api.sensor_type}: ${api.analysis.status}` : '',
      recommendations: rec,
      ollama_model: oa.model_used || '',
      ollama_ia_active: iaOk,
      api_response: api,
    },
  },
];
